# Code generated by Claude
"""
Characterise the solver's "snap": near a straight elbow (joint 4 close to 0) the
OpenArm retargeting solver can return joints that differ a lot from the ones the
input pose was made from, with the wrist point off by centimetres.

Headless, kinematic, no viewer. Uses the shared helper src/safety_filter.py
(joint angles -> robot FK -> RetargetFrame -> solve) and changes no existing file.

    python experiments/elbow_snap_sweep.py            # everything, writes the plot
    python experiments/elbow_snap_sweep.py --out data/elbow_snap

  1. The failing configs of safety_filter_roundtrip.py --spread 0: their commanded
     joint 4.
  2. Sweep of commanded joint 4 from 0.6 down to 0 (0.002 rad steps) on realistic
     poses for each arm (joints 1-3 and 5-7 fixed, each step's output fed back as
     q_current). Records where the output first snaps, the output joint 4 right
     after, and the wrist (W) position error in mm.
  3. Is the snap angle the same across configs? Hysteresis: sweep joint 4 back up.
  4. The same sweeps with the solver option limited=True.
  5. A plot of commanded vs output joint 4.

How "snap" is detected: the first step where any output joint changes by more than
SNAP_STEP (0.05 rad) from the previous step, while the command moves 0.002 rad.
The wrist error is the distance between FK(output).W and the input W (the point
sent to the solver), from the solver's own robot_fk_at().
"""

import argparse
import sys
from pathlib import Path

import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src.safety_filter import SafetyFilter  # noqa: E402

SIDES = ("left", "right")
J4_START, J4_END, J4_STEP = 0.6, 0.0, 0.002
SNAP_STEP = 0.05          # rad of output change in one 0.002 rad command step
np.set_printoptions(precision=3, suppress=True, linewidth=150)


# ------------------------------------------------------------ solver variants
class LimitedFilter(SafetyFilter):
    """SafetyFilter whose session is built with the solver option limited=True."""

    def __init__(self, collision_avoidance=True):
        from openarm_teleop.session import make_session
        self.collision_avoidance = collision_avoidance
        self.session = make_session(
            collision_avoidance=collision_avoidance, functional_offset=False,
            retarget_mode="pose", limited=True)
        self.default_q = {s: np.asarray(self.session.default_q[s], dtype=float)
                          for s in SIDES}


def arm_points(sf, arm, q):
    """S, E, W of one arm from the solver's own FK (the other arm at default)."""
    kw = ({"q_left": q, "q_right": sf.default_q["right"]} if arm == "left"
          else {"q_right": q, "q_left": sf.default_q["left"]})
    f = sf.session.robot_fk_at(**kw)[arm]
    return np.asarray(f["S"]), np.asarray(f["E"]), np.asarray(f["W"])


# ------------------------------------------------------------ poses
# Direction of the arm (shoulder -> wrist, solver frame: x forward, y toward the
# robot's LEFT, z up) for the LEFT arm; the right arm uses the mirror image (y flipped).
POSES = [
    ("forward at shoulder height", (1.0, 0.0, 0.0),
     "arm straight out in front, hand at shoulder height"),
    ("forward and down to bench", (0.64, 0.0, -0.77),
     "arm reaching forward and 50 deg downward, as toward the bench top (the bench top is "
     "0.64 m below the shoulders at the current pedestal height, farther than the arm reaches, "
     "so this is the direction only)"),
    ("down to the side", (0.15, 0.55, -0.82),
     "arm angled down and out to the side about 33 deg from vertical, slightly forward"),
    ("hanging at rest", (0.0, 0.0, -1.0),
     "arm hanging straight down at the side"),
    ("reaching up", (0.60, 0.10, 0.79),
     "arm forward and up about 50 deg, as to a shelf"),
    ("across the body", (0.62, -0.75, -0.2),
     "arm forward and swung inward across the body toward the other arm's side "
     "(the joint limits allow only part of this; the achieved direction is reported)"),
]
WRIST_VARIANTS = {"base": (0.0, 0.0, 0.0), "wristA": (0.5, 0.4, 0.8), "wristB": (-0.6, -0.4, -0.9)}


def _rot_about(axis, angle):
    axis = np.asarray(axis, float) / np.linalg.norm(axis)
    K = np.array([[0, -axis[2], axis[1]], [axis[2], 0, -axis[0]], [-axis[1], axis[0], 0]])
    return np.eye(3) + np.sin(angle) * K + (1 - np.cos(angle)) * (K @ K)


def joints_for_direction(sf, arm, direction, limits, j4=0.3):
    """Joints 1-3 that point the arm (shoulder -> wrist) along `direction`.

    Grid search over joints 1 and 2 (and a few joint 3 twists) with joint 4 = 0.3, the
    middle of the sweep. Returns (j1, j2, j3, angle error in deg).
    """
    d = np.asarray(direction, float) / np.linalg.norm(direction)
    lo, hi = limits
    best = (9.9, None)
    for j3 in (-1.0, -0.5, 0.0, 0.5, 1.0):
        for j1 in np.arange(lo[0] + 0.02, hi[0], 0.1):
            for j2 in np.arange(lo[1] + 0.02, hi[1], 0.1):
                S, _, W = arm_points(sf, arm, np.array([j1, j2, j3, j4, 0, 0, 0.0]))
                v = (W - S) / np.linalg.norm(W - S)
                cost = np.arccos(np.clip(v @ d, -1, 1)) + 0.02 * abs(j3)
                if cost < best[0]:
                    best = (cost, (j1, j2, j3))
    j1, j2, j3 = best[1]
    S, _, W = arm_points(sf, arm, np.array([j1, j2, j3, j4, 0, 0, 0.0]))
    v = (W - S) / np.linalg.norm(W - S)
    return j1, j2, j3, float(np.degrees(np.arccos(np.clip(v @ d, -1, 1))))


def build_configs(sf, limits):
    """All sweep configs: dict(name, arm, pose, variant, q (j4 slot = nan), achieved)."""
    configs = []
    for arm in SIDES:
        for pname, d, _ in POSES:
            d_arm = np.array(d) * (1 if arm == "left" else np.array([1, -1, 1]))
            variants = {"base": d_arm}
            variants["dir+"] = _rot_about((0, 0, 1), +0.15) @ d_arm          # yawed 0.15 rad
            variants["dir-"] = _rot_about(np.cross((0, 0, 1), d_arm), -0.15) @ d_arm \
                if abs(d_arm[2]) < 0.999 else _rot_about((0, 1, 0), -0.15) @ d_arm   # tilted
            for vname, dv in variants.items():
                j1, j2, j3, err = joints_for_direction(sf, arm, dv, limits[arm])
                for wname, w in WRIST_VARIANTS.items():
                    if vname != "base" and wname != "base":
                        continue                         # wrist variants only on the base direction
                    q = np.array([j1, j2, j3, np.nan, *w])
                    tag = vname if wname == "base" else wname
                    configs.append(dict(arm=arm, pose=pname, variant=tag, q=q, dir_err=err,
                                        name=f"{arm}/{pname}/{tag}"))
    return configs


# ------------------------------------------------------------ sweeps
def run_sweep(sf, arm, q_fixed, j4_values, q_start=None, reset=True):
    """Sweep commanded joint 4; each step's output is fed back as q_current.

    Returns dict of arrays: j4_cmd, out (n,7), cmd (n,7), werr_mm (n,). The other arm
    stays at the solver default pose.
    """
    other = sf.default_q["right" if arm == "left" else "left"]
    n = len(j4_values)
    cmd = np.tile(q_fixed, (n, 1)); cmd[:, 3] = j4_values
    out = np.zeros((n, 7)); werr = np.zeros(n)
    cur = cmd[0].copy() if q_start is None else q_start.copy()
    for i in range(n):
        left, right = (cmd[i], other) if arm == "left" else (other, cmd[i])
        cl, cr = (cur, other) if arm == "left" else (other, cur)
        ql, qr = sf.filter(left, right, q_current_left=cl, q_current_right=cr,
                           reset=(reset and i == 0))
        out[i] = ql if arm == "left" else qr
        cur = out[i].copy()
        werr[i] = 1000.0 * np.linalg.norm(arm_points(sf, arm, out[i])[2]
                                          - arm_points(sf, arm, cmd[i])[2])
    return dict(j4_cmd=np.asarray(j4_values), out=out, cmd=cmd, werr_mm=werr)


def find_snap(res):
    """First step where the output jumps; None if it never does."""
    step = np.abs(np.diff(res["out"], axis=0)).max(axis=1)
    hit = np.where(step > SNAP_STEP)[0]
    if len(hit) == 0:
        return None
    i = int(hit[0]) + 1
    return dict(i=i, j4_cmd=float(res["j4_cmd"][i]), j4_prev_cmd=float(res["j4_cmd"][i - 1]),
                j4_out=float(res["out"][i, 3]), size=float(step[i - 1]),
                joints=[int(j) + 1 for j in np.where(np.abs(res["out"][i] - res["out"][i - 1]) > 0.25 * step[i - 1])[0]],
                werr_after=float(res["werr_mm"][i]), werr_end=float(res["werr_mm"][-1]))


def reach_ratio(sf, arm, q):
    """|S-W| / (|S-E| + |E-W|): 1.0 = arm fully straight."""
    S, E, W = arm_points(sf, arm, q)
    return float(np.linalg.norm(W - S) / (np.linalg.norm(E - S) + np.linalg.norm(W - E)))


def off_range(res, tol=1e-3):
    """(lowest, highest) commanded j4 where the output differs from the command, or None."""
    off = np.abs(res["out"] - res["cmd"]).max(axis=1) > tol
    if not off.any():
        return None
    v = res["j4_cmd"][off]
    return float(v.min()), float(v.max())


def j4_values_down():
    return np.round(np.arange(J4_START, J4_END - 1e-9, -J4_STEP), 6)


# ------------------------------------------------------------ main
def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--out", default="data/elbow_snap")
    args = ap.parse_args()
    out_dir = PROJECT_ROOT / args.out
    out_dir.mkdir(parents=True, exist_ok=True)

    sf = SafetyFilter(True)
    off = SafetyFilter(False)                       # control only
    import openarm_teleop
    spec = np.load(Path(openarm_teleop.__file__).parent / "assets/specs/openarm_v1.npz")
    limits = {a: (spec[f"{a}_arm/joint_lower"], spec[f"{a}_arm/joint_upper"]) for a in SIDES}
    print(f"joint 4 range: [{limits['left'][0][3]:.3f}, {limits['left'][1][3]:.3f}] rad "
          f"(lower limit {limits['left'][0][3]:.3f})")

    # ---------------------------------------------------------- 1. the 9 failing configs
    from experiments.safety_filter_roundtrip import branch_failures
    fails = branch_failures(seed=0, spread=0.0)
    print("\n" + "=" * 100 + "\n1. COMMANDED JOINT 4 OF THE FAILING CONFIGS (safety_filter_roundtrip.py --spread 0)\n" + "=" * 100)
    print(f"{'idx':>3} {'arm':5s} {'cmd j4':>8} {'out j4':>8} {'max err':>8}  worst joints          other cmd joints (j1 j2 j3 | j5 j6 j7)")
    for i, f in enumerate(fails):
        top = np.argsort(-f["joints"])[:2]
        q = f["q"]
        print(f"{i:3d} {f['arm']:5s} {q[3]:8.3f} {f['out'][3]:8.3f} {f['error']:8.3f}  "
              + ", ".join(f"j{j + 1} {f['joints'][j]:.2f}" for j in top).ljust(22)
              + f"{q[:3]} | {q[4:]}")
    j4s = np.array([f["q"][3] for f in fails])
    print(f"-> commanded j4 of the 9 failures: min {j4s.min():.3f}, max {j4s.max():.3f}, median {np.median(j4s):.3f} rad; "
          f"{(j4s < 0.3).sum()}/9 below 0.3, {(j4s < 0.1).sum()}/9 below 0.1")

    # ---------------------------------------------------------- 2. sweeps
    print("\n" + "=" * 100 + "\n2. THRESHOLD SWEEP: commanded joint 4 from 0.6 down to 0 (step 0.002), joints 1-3, 5-7 fixed\n" + "=" * 100)
    print("Poses (left arm; the right arm is the mirror image). Joints 1-3 found by search for the arm direction;")
    configs = build_configs(sf, limits)
    for pname, d, desc in POSES:
        ex = next(c for c in configs if c["pose"] == pname and c["arm"] == "left" and c["variant"] == "base")
        S, _, W = arm_points(sf, "left", np.array([*ex["q"][:3], 0.3, *ex["q"][4:]]))
        print(f"  - {pname}: {desc}.\n      left base joints 1-3 = {ex['q'][:3]}, direction error {ex['dir_err']:.1f} deg, "
              f"wrist at {np.round(W - S, 3)} from the shoulder")
    print("Variants per pose: base; dir+ (direction yawed 0.15 rad); dir- (tilted 0.15 rad); "
          "wristA (j5,j6,j7 = 0.5,0.4,0.8); wristB (-0.6,-0.4,-0.9).\n")
    results = []
    for c in configs:
        res = run_sweep(sf, c["arm"], c["q"], j4s_down := j4_values_down())
        c["res"], c["snap"] = res, find_snap(res)
        ctrl = run_sweep(off, c["arm"], c["q"], j4s_down)                    # control, filter OFF
        c["snap_off"] = find_snap(ctrl)
        c["werr0"] = float(res["werr_mm"][0])
    print(f"{'config':44s} {'snap@cmd j4':>11} {'out j4 after':>12} {'size rad':>8} {'joints':>9} "
          f"{'W err after':>11} {'W err end':>10} {'W err @0.6':>10}")
    for c in configs:
        s = c["snap"]
        if s is None:
            print(f"{c['name']:44s} {'never snaps':>11}  {'':>12} {'':>8} {'':>9} {'':>11} "
                  f"{c['res']['werr_mm'][-1]:9.1f}mm {c['werr0']:9.1f}mm")
        else:
            print(f"{c['name']:44s} {s['j4_cmd']:11.3f} {s['j4_out']:12.3f} {s['size']:8.2f} "
                  f"{','.join('j' + str(j) for j in s['joints']):>9} {s['werr_after']:9.1f}mm "
                  f"{s['werr_end']:8.1f}mm {c['werr0']:8.1f}mm")
    snapped = [c for c in configs if c["snap"] is not None]
    print(f"\n{len(snapped)}/{len(configs)} sweeps snap; never snap: "
          f"{[c['name'] for c in configs if c['snap'] is None] or 'none'}")
    print(f"Filter OFF control: snap angle identical to filter ON in "
          f"{sum(1 for c in configs if (c['snap'] is None) == (c['snap_off'] is None) and (c['snap'] is None or abs(c['snap']['j4_cmd'] - c['snap_off']['j4_cmd']) < 1e-9))}/{len(configs)} sweeps")

    # ---------------------------------------------------------- 3. is the snap angle constant?
    print("\n" + "=" * 100 + "\n3. IS THE SNAP ANGLE THE SAME ACROSS CONFIGS?\n" + "=" * 100)
    sa = np.array([c["snap"]["j4_cmd"] for c in snapped])
    print(f"snap at commanded j4: min {sa.min():.3f}, median {np.median(sa):.3f}, max {sa.max():.3f} rad "
          f"(std {sa.std():.3f}); output j4 right after: min {min(c['snap']['j4_out'] for c in snapped):.3f}, "
          f"max {max(c['snap']['j4_out'] for c in snapped):.3f}")
    for arm in SIDES:
        a = np.array([c["snap"]["j4_cmd"] for c in snapped if c["arm"] == arm])
        print(f"   {arm:5s}: n={len(a)}  min {a.min():.3f}  median {np.median(a):.3f}  max {a.max():.3f}")
    for pname, _, _ in POSES:
        a = np.array([c["snap"]["j4_cmd"] for c in snapped if c["pose"] == pname])
        if len(a):
            print(f"   {pname:30s}: n={len(a):2d}  min {a.min():.3f}  median {np.median(a):.3f}  max {a.max():.3f}")
    rr = np.array([reach_ratio(sf, c["arm"], c["res"]["cmd"][c["snap"]["i"]]) for c in snapped])
    rr_prev = np.array([reach_ratio(sf, c["arm"], c["res"]["cmd"][c["snap"]["i"] - 1]) for c in snapped])
    print(f"arm extension at the snap step (|S-W| / full length; 1 = straight): min {rr.min():.4f}, max {rr.max():.4f} "
          f"(step before: {rr_prev.min():.4f}..{rr_prev.max():.4f}); for the 0.242 group: "
          f"{np.mean([r for r, c in zip(rr, snapped) if abs(c['snap']['j4_cmd'] - 0.242) < 1e-9]):.4f}")
    peak = [(float(c["res"]["werr_mm"][c["snap"]["i"]:].max()),
             float(c["res"]["j4_cmd"][c["snap"]["i"] + int(np.argmax(c["res"]["werr_mm"][c["snap"]["i"]:]))]))
            for c in snapped]
    pk = np.array([p[0] for p in peak])
    print(f"wrist error after the snap (peak over the rest of the sweep): min {pk.min():.1f}, median {np.median(pk):.1f}, "
          f"max {pk.max():.1f} mm; it goes back to ~0 at j4 = 0 (end errors: max {max(c['snap']['werr_end'] for c in snapped):.1f} mm)")
    zero_wrist = [c for c in configs if c["variant"] in ("base", "dir+", "dir-") and c["pose"] != "hanging at rest"]
    print(f"configs with joints 5-7 all zero (not the hanging pose): {sum(c['snap'] is not None for c in zero_wrist)}/{len(zero_wrist)} snap; "
          f"with non-zero wrist angles (wristA/B): {sum(c['snap'] is not None for c in configs if c['variant'].startswith('wrist'))}"
          f"/{sum(1 for c in configs if c['variant'].startswith('wrist'))} snap")
    print("\nHysteresis: continue each of these sweeps back UP (0 -> 0.6) from the snapped state "
          "(output fed back), and also restart upward from a fresh solver at j4 = 0:")
    hyst = []
    for c in snapped[:: max(1, len(snapped) // 5)][:5]:
        up_vals = np.round(np.arange(0.0, J4_START + 1e-9, J4_STEP), 6)
        cont = run_sweep(sf, c["arm"], c["q"], up_vals, q_start=c["res"]["out"][-1], reset=False)
        fresh = run_sweep(sf, c["arm"], c["q"], up_vals)

        def back(r):
            err = np.abs(r["out"] - r["cmd"]).max(axis=1)
            ok = np.where(err < 1e-3)[0]
            return None if len(ok) == 0 else float(r["j4_cmd"][ok[0]])
        hyst.append((c, cont, fresh, back(cont), back(fresh)))
        f = lambda v: "never" if v is None else f"{v:.3f}"
        g = lambda r: "none" if r is None else f"{r[0]:.3f}..{r[1]:.3f}"
        print(f"   {c['name']:44s} down: snaps at {c['snap']['j4_cmd']:.3f}, off the command for j4 in {g(off_range(c['res']))}; "
              f"up (continued): back on it at {f(back(cont))}, off for {g(off_range(cont))}; "
              f"up (fresh solver): off for {g(off_range(fresh))}")

    # ---------------------------------------------------------- 4. limited=True
    print("\n" + "=" * 100 + "\n4. SAME SWEEPS WITH THE SOLVER OPTION limited=True\n" + "=" * 100)
    try:
        lim = LimitedFilter(True)
    except Exception as e:                                   # noqa: BLE001
        lim = None
        print(f"limited=True could not be built for OpenArm: {type(e).__name__}: {e}")
    lim_rows = []
    diffs = []
    if lim is not None:
        pick = snapped[:: max(1, len(snapped) // 8)][:8] + [c for c in configs if c["snap"] is None][:2]
        print(f"{'config':44s} {'default snap':>12} {'limited snap':>12} {'out j4 after':>12} {'W err end (default/limited)':>28}")
        for c in pick:
            r2 = run_sweep(lim, c["arm"], c["q"], j4_values_down())
            s2 = find_snap(r2)
            lim_rows.append((c, r2, s2))
            d1 = "never" if c["snap"] is None else f"{c['snap']['j4_cmd']:.3f}"
            d2 = "never" if s2 is None else f"{s2['j4_cmd']:.3f}"
            o2 = "" if s2 is None else f"{s2['j4_out']:.3f}"
            same_out = float(np.abs(r2["out"] - c["res"]["out"]).max())
            print(f"{c['name']:44s} {d1:>12} {d2:>12} {o2:>12} {c['res']['werr_mm'][-1]:11.1f} / {r2['werr_mm'][-1]:.1f} mm"
                  f"   (max output difference vs default {same_out:.1e} rad)")
        n_same = sum(1 for c, r2, s2 in lim_rows if np.abs(r2["out"] - c["res"]["out"]).max() < 1e-6)
        print(f"-> outputs identical to the default session in {n_same}/{len(lim_rows)} sweeps (the sample above)")
        diffs = []
        for c in configs:
            r2 = run_sweep(lim, c["arm"], c["q"], j4_values_down())
            diffs.append((c, r2, find_snap(r2), float(np.abs(r2["out"] - c["res"]["out"]).max())))
        same = [d for d in diffs if d[3] < 1e-6]
        print(f"ALL {len(configs)} sweeps: limited=True output identical (<1e-6 rad) in {len(same)}; differs in {len(diffs) - len(same)}:")
        for c, r2, s2, dmax in diffs:
            if dmax >= 1e-6:
                a = "never" if c["snap"] is None else f"{c['snap']['j4_cmd']:.3f}"
                b = "never" if s2 is None else f"{s2['j4_cmd']:.3f}"
                print(f"     {c['name']:44s} max output difference {dmax:.3g} rad; snap default {a} -> limited {b}; "
                      f"W error at end default {c['res']['werr_mm'][-1]:.1f} mm -> limited {r2['werr_mm'][-1]:.1f} mm "
                      f"(peak {r2['werr_mm'].max():.1f} mm)")

    # ---------------------------------------------------------- 5. plot
    save_plot(out_dir / "j4_sweeps.png", configs, snapped, hyst,
              [(c, r2, s2) for c, r2, s2, _ in diffs] if lim is not None else [])
    print(f"\nSaved {out_dir / 'j4_sweeps.png'}")


def save_plot(path, configs, snapped, hyst, lim_rows):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    INK, INK2, GRID, SURFACE = "#0b0b0b", "#52514e", "#e4e3df", "#fcfcfb"
    BLUE, ORANGE = "#2a78d6", "#eb6834"                      # validated CVD-safe pair
    lim_by_name = {c["name"]: (r2, s2) for c, r2, s2 in lim_rows}
    pick = []
    for pname, _, _ in POSES[:5]:
        for variant in ("wristB", "wristA", "base"):
            cand = [c for c in snapped if c["pose"] == pname and c["arm"] == "left" and c["variant"] == variant]
            if cand:
                pick.append(cand[0])
                break
    fig, axes = plt.subplots(2, 3, figsize=(12.5, 7.4), facecolor=SURFACE)
    axes = axes.ravel()
    for ax, c in zip(axes, pick):
        r = c["res"]
        ax.plot([0.6, 0], [0.6, 0], color="#8c8b86", lw=1.2, ls=":", label="output = command")
        ax.plot(r["j4_cmd"], r["out"][:, 3], color=BLUE, lw=2, label="output (default)")
        if c["name"] in lim_by_name:
            r2, _ = lim_by_name[c["name"]]
            ax.plot(r2["j4_cmd"], r2["out"][:, 3], color=ORANGE, lw=1.2, ls="--", label="output (limited=True)")
        s = c["snap"]
        ax.plot([s["j4_cmd"]], [s["j4_out"]], "o", color=INK, ms=5, zorder=5)
        ax.annotate(f"snap at {s['j4_cmd']:.3f}\nW error {s['werr_after']:.0f} mm", xy=(s["j4_cmd"], s["j4_out"]),
                    xytext=(0.52, 0.22), textcoords="axes fraction", color=INK, fontsize=8,
                    arrowprops=dict(arrowstyle="->", color=INK2, lw=0.8))
        ax.set_title(c["name"], color=INK, fontsize=9.5, loc="left")
    # hysteresis panel
    ax = axes[5]
    if hyst:
        c, cont, fresh, b_cont, b_fresh = max(hyst, key=lambda h: h[0]["snap"]["size"])   # a big snap shows best
        ax.plot([0, 0.6], [0, 0.6], color="#8c8b86", lw=1.2, ls=":", label="output = command")
        ax.plot(c["res"]["j4_cmd"], c["res"]["out"][:, 3], color=BLUE, lw=2, label="sweep down 0.6 -> 0")
        ax.plot(cont["j4_cmd"], cont["out"][:, 3], color=ORANGE, lw=1.4, ls="--", label="then back up 0 -> 0.6")
        ax.set_title(f"hysteresis: {c['name']}", color=INK, fontsize=9.5, loc="left")
    for ax in axes:
        ax.set_facecolor(SURFACE)
        ax.set_xlabel("commanded joint 4 (rad)", color=INK2, fontsize=8.5)
        ax.set_ylabel("output joint 4 (rad)", color=INK2, fontsize=8.5)
        ax.grid(color=GRID, lw=0.8)
        ax.tick_params(colors=INK2, labelsize=8)
        for side in ("top", "right"):
            ax.spines[side].set_visible(False)
        for side in ("left", "bottom"):
            ax.spines[side].set_color("#b9b8b2")
        ax.legend(loc="upper left", frameon=False, fontsize=7.5, labelcolor=INK2)
    fig.suptitle("Solver output joint 4 vs commanded joint 4 (joints 1-3, 5-7 held fixed); dot = first snap",
                 color=INK, fontsize=11, x=0.01, ha="left")
    fig.tight_layout(rect=(0, 0, 1, 0.96))
    fig.savefig(path, dpi=140, facecolor=SURFACE)


if __name__ == "__main__":
    main()
